pos = 1
for _ in range(int(data[0])):
    n, k = int(data[pos]), int(data[pos + 1])
    sizes = [int(item) for item in data[pos + 2 : pos + 2 + n]]
    pos += 2 + n
    low, high = max(sizes), sum(sizes)
    while low < high:
        middle = (low + high) // 2
        packs, load = 1, 0
        for size in sizes:
            if load + size > middle:
                packs += 1
                load = size
            else:
                load += size
        if packs <= k:
            high = middle
        else:
            low = middle + 1
    print(low)

import sys

data = sys.stdin.read().split()
pos = 1
for _ in range(int(data[0])):
    n, k = int(data[pos]), int(data[pos + 1])
    kinds = [int(item) for item in data[pos + 2 : pos + 2 + n]]
    pos += 2 + n
    inside = [0] * (k + 1)
    missing = k
    best = left = 0
    for right, kind in enumerate(kinds):
        if kind <= k:
            if inside[kind] == 0:
                missing -= 1
            inside[kind] += 1
        while missing == 0:
            if best == 0 or right - left + 1 < best:
                best = right - left + 1
            gone = kinds[left]
            left += 1
            if gone <= k:
                inside[gone] -= 1
                if inside[gone] == 0:
                    missing += 1
    print(best)

