rules = [
    (data[2 + 3 * i] == "allow", int(data[3 + 3 * i]), int(data[4 + 3 * i])) for i in range(count)
]
edges = sorted({low for _, low, _ in rules} | {high + 1 for _, _, high in rules})
opened = 0
for start, end in zip(edges, edges[1:]):
